<script lang="ts">
 import {page} from '$app/stores';import {documents,openCreate} from '$lib/workspace';import {labels,excerpt} from '$lib/journey.mjs';import Icon from '$lib/Icon.svelte';
 let search='',filter=$page.url.searchParams.get('type')||'';
 $: rows=$documents.filter(d=>(!filter||d.doc_type===filter)&&(!search||`${d.title} ${d.body_md}`.toLowerCase().includes(search.toLowerCase())));
 $: types=[...new Set($documents.map(d=>d.doc_type))];
</script>
<div class="page-heading"><span class="eyebrow">YOUR PERSONAL LIBRARY</span><h1>A place for every thought.</h1><p>Interests, experiments, stories, and the notes in between.</p></div><div class="library-toolbar"><input class="search-input" type="search" bind:value={search} aria-label="Search your documents" placeholder="Find a thought, a topic, a phrase…"/><select bind:value={filter} aria-label="Filter document type"><option value="">All documents</option>{#each types as type}<option value={type}>{labels[type]||type}</option>{/each}</select><button class="button primary" on:click={()=>openCreate('idea')}><Icon name="plus" size={16}/>New draft</button></div><div class="document-table"><div class="document-table-heading"><span>DOCUMENT</span><span>TYPE</span><span>VERSION</span><span></span></div>{#each rows as doc}<a href={doc.doc_type==='experiment'?`/experiments/?id=${doc.revision.document_id}`:`/documents/?id=${doc.revision.document_id}`} class="document-table-row"><div><strong>{doc.title}</strong><p>{excerpt(doc.body_md,90)||'Room to keep writing.'}</p></div><span class="document-type">{labels[doc.doc_type]||doc.doc_type}</span><span class="fine">v{doc.revision.revision_number}</span><Icon name="arrow" size={17}/></a>{:else}<div class="empty-card"><Icon name="book" size={28}/><h3>{search?'No matching notes yet.':'Your library has room to grow.'}</h3><p>{search?'Try a different phrase or clear the filters.':'Start with an interest or an idea.'}</p></div>{/each}</div>
